import "strings"
import "regexp"
from(bucket: "Homeassistant")
  |> range(start: -7d, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._field == "value" and r.entity_id =~ /^.+_climat_(temperature)$/)
  |> last()
  |> map(fn: (r) => {
      room = strings.replaceAll(v: regexp.replaceAllString(r: /^(.+)_climat_(?:temperature)$/, v: r.entity_id, t: "\${1}"), t: "_", u: " ")
      return {_time: r._time, _value: float(v: r._value),
              _field: strings.toUpper(v: strings.substring(v: room, start: 0, end: 1)) + strings.substring(v: room, start: 1, end: strings.strlen(v: room))}
  })
  |> group(columns: ["_field"])

